-- 버전을 붙인다

@Entity
public class Item {
    @Id @GeneratedValue private Long id;
    private String name;
    private int stock;

    @Version
    private Long version;
}

@Test
@Transactional
void 버전_동작() {
    Item i = itemRepository.save(new Item("연필", 10));
    em.flush();
    System.out.println("버전: " + i.getVersion());

    i.setStock(9);
    em.flush();
    System.out.println("고친 뒤 버전: " + i.getVersion());
}

