-- 다시 갱신 분실을 시도한다

@Test
void 낙관적_락() throws Exception {
    Long id = tx(() -> itemRepository.save(new Item("연필", 10)).getId());

    List<String> results = Collections.synchronizedList(new ArrayList<>());
    CountDownLatch read = new CountDownLatch(2);
    Runnable order = () -> {
        try {
            tx(() -> {
                Item i = itemRepository.findById(id).orElseThrow();
                read.countDown(); await(read);
                i.setStock(i.getStock() - 1);
                return null;
            });
            results.add("성공");
        } catch (Exception e) {
            results.add(e.getClass().getSimpleName());
        }
    };

    Thread a = new Thread(order), b = new Thread(order);
    a.start(); b.start(); a.join(); b.join();

    System.out.println("결과: " + results);
    System.out.println("남은 재고: " +
            tx(() -> itemRepository.findById(id).orElseThrow().getStock()));
}

