@Test
void 비관적_동작() throws Exception {
    Long id = tx(() -> itemRepository.save(new Item("연필", 10)).getId());

    Runnable order = () -> tx(() -> {
        long t = System.nanoTime();
        Item i = itemRepository.findWithLockById(id).orElseThrow();
        System.out.printf("  읽기까지 %d ms%n",
                (System.nanoTime() - t) / 1_000_000);
        i.setStock(i.getStock() - 1);
        sleep(300);
        return null;
    });

    Thread a = new Thread(order), b = new Thread(order);
    a.start(); sleep(50); b.start(); a.join(); b.join();

    System.out.println("남은 재고: " +
            tx(() -> itemRepository.findById(id).orElseThrow().getStock()));
}

