-- 벌크는 버전을 안 올린다

@Modifying(clearAutomatically = true)
@Query("update Item i set i.stock = i.stock - 1 where i.id = :id")
int decrease(@Param("id") Long id);

@Test
@Transactional
void 벌크와_버전() {
    Long v0 = (Long) em.createNativeQuery(
            "select version from item where id = 1").getSingleResult();
    itemRepository.decrease(1L);
    Long v1 = (Long) em.createNativeQuery(
            "select version from item where id = 1").getSingleResult();
    System.out.println("버전: " + v0 + " -> " + v1);
}

